INSERT OR REPLACE INTO profile VALUES('1', 'Khalid Atthoriq', 'Fullstack Creative Developer', 'I design interfaces and build them to work.', 'I build fullstack apps, design interfaces, and create visual content.', 'I study Informatics Engineering at State Polytechnic of Malang. My work blends engineering with creative direction, so the result is functional and still has personality.', 'Build it clean. Make it workable. Give it character, soul, and life.', 'I keep layouts editorial and structured, but still easy for people to use.', 'I care about clear hierarchy, strong visuals, and smooth interactions.', '/CV%20-%20Muhammad%20Khalid%20Atthoriq.pdf');
