INSERT OR REPLACE INTO projects VALUES('prog1', 'programming', 'Novaris Risk Assesment', '/media/projects%2F1787116435379-829411c0-fe84-404c-bcc6-748f7a29d11d-screenshot-20260819-095633.png', 'Novaris is a Decision Support System for SMEs that helps businesses make smarter, more informed decisions by analyzing project options, risks, vendors, and potential ROI. It simplifies complex data into clear recommendations, helping businesses understand what to choose, why it makes sense, and what results they can expect.', NULL, NULL, NULL, 'https://novaris-six.vercel.app/', '0', 'Frontend Developer | UI/UX Designer', 'Typescript | React Vite | Tailwind', '2025', 'https://github.com/KhalidFinny/Novaris-Project', '["/media/projects%2F1787116435553-319fcb5f-ef2c-4321-b913-1606ccf90804-screenshot-20260819-100727.png"]', 'done');
INSERT OR REPLACE INTO projects VALUES('prog2', 'programming', 'Visit Malangg', '/media/projects/1787125471204-c934e49b-f6ec-44a7-8c83-5444152f6854-screenshot-20260819-143718.webp', 'Visit Malang is a tourism website designed to help visitors explore Malang more easily, featuring interactive maps to quickly discover places, a travel planner to manage and estimate holiday spending, and useful information about the city, all in one convenient platform.', NULL, NULL, NULL, 'https://www.visitmalang.id/', '1', 'Frontend Developer | UI/UX Designer | Lead Developer', 'React | TypeScript | Tailwind CSS | Tanstack', '2026', 'https://github.com/KhalidFinny/Novaris-Project', '["/media/projects/1787125471248-65e11661-0fca-450f-ada6-77e9301efc66-screenshot-20260819-143751.webp","/media/projects/1787125471253-53a35d89-30c6-4e99-b3aa-18880d0016ad-screenshot-20260819-143806.webp"]', 'done');
INSERT OR REPLACE INTO projects VALUES('prog3', 'programming', 'Eleanore', '/media/projects/1787129429438-fe21a87f-8d00-4118-b667-4315cf9a41b0-screenshot-20260819-155005.webp', 'Eleanore is my custom built AI Agent, replicating opencode and omp its fully customized to my prefrence using deepseek harness as the framwork harness.', NULL, NULL, NULL, NULL, '2', 'Fullstack Developer', 'React | TypeScript', '2026', NULL, '[]', 'ongoing');
INSERT OR REPLACE INTO projects VALUES('prog4', 'programming', 'PlayList Event Music player', '/media/projects/1787130301126-f8ef82a8-23fd-4142-993c-cc27465ea070-screenshot-20260819-155829.webp', 'PlayList is a music queue web app designed for shared listening and large events, allowing people to discover, add, and manage songs in a collaborative queue without interrupting the flow of the event.', NULL, NULL, NULL, 'https://playlist.fiinnyy.my.id/', '3', 'Fullstack Developer', 'React | TypeScript | PostgreSQL', '2026', 'https://github.com/KhalidFinny/playList', '[]', 'done');
INSERT OR REPLACE INTO experiences VALUES('exp0', 'Front-end Developer Intern', 'PT Intelix Global Crossing', 'Malang, Indonesia', 'July 2026 - Present', '["Optimized front-end performance using TanStack libraries.", "Modernized product UI designs with modern UX principles.", "Optimized query handling with TanStack Query for faster API queries."]', 'work', '0');
